// x tiling, y tiling, x offset, y offset
#define _Tiling vec4(11., 3., 0., 0.)

// Billboard vs forward motion animation toggle (0 or 1)
#define  _Billboard 1.

// active section color
#define  _ActiveColor vec4(0., 0.7, 0.8, 1.)

// guideline color
#define  _LineColor vec4(0.2)

// flip uv's
#define  _Flipped 0.

// flow speed
#define  _Speed 0.3

// active section length
#define  _ActiveLength 2.

// active sections on screen (only makes sense if divisor of _Tiling.x)
//#define  _ActiveCount 2.

// arrow cutout 0.25 - 0.5
#define  _Cutout 0.36

#define _Time vec2(iTime, iTime)

//Clip arrow at the bottom to prevent flickering from it bleeding into the previous tile. 
//Appears when working with a 3D camera due to inaccuracies.
#define _BottomClip 0.01

float _ActiveCount = 2.;

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    _ActiveCount = _Tiling.x / floor(_Tiling.x / _ActiveCount);
//VERTEX CALC
    vec2 uv = fragCoord/iResolution.xy;    

    float fMotion = - _Time.y * (1.-_Billboard) * _Speed * _Tiling.x;
    vec2 motion;

    motion.x += fMotion * (1. - _Flipped);
    motion.y += fMotion * _Flipped;    

    uv = uv * _Tiling.xy + _Tiling.zw + motion;

    uv = uv * _Flipped + (1. - _Flipped) * uv.yx;
    vec2 uvI = uv;
//VERTEX CALC END

    uv.y = mod(.5 * uv.y, 0.5);// resize to fit arrow to the whole tile and mod to make it seamless. comment to see what happens otherwise

    float tiles = _Tiling.x / _ActiveCount;    

    //Active segment determination

    float tileIndex = floor(mod(uvI.y, tiles));
    float movement = _Time.y * _Billboard * _Speed;
    float activeTile = float(int(fract(movement * _ActiveCount) * tiles));

    float activeDistance = _ActiveLength - 1.;
    float isActive = step(mod(tileIndex - activeTile + tiles, tiles), activeDistance);

    //Shape
    float cutout = _Cutout;

    float left = step((fract(uv.x) + fract(uv.y)) / 2., .5);
    float right = step((1. - fract(uv.x) + fract(uv.y)) / 2., .5);

    float leftCut = step((fract(uv.x) + fract(uv.y)) / 2., cutout);
    float rightCut = step((1. - fract(uv.x) + fract(uv.y)) / 2., cutout);
    float mask = left * right;
    mask -= leftCut * rightCut;

#ifdef _BottomClip    
    mask *= step(_BottomClip, uv.y);
#endif

    //Color

    vec4 color = _LineColor * (1. - isActive) + _ActiveColor * isActive;
    color *= mask;


    fragColor = color;
}
